    id              bigint        IDENTITY(1,1) PRIMARY KEY,
    ts_utc          datetime2     NOT NULL,
    instance_name   sysname       NOT NULL,
    base_datos      sysname       NULL,
    archivo         nvarchar(260) NULL,
    lectura_ms      decimal(18,6) NULL,
    escritura_ms    decimal(18,6) NULL,
    estado          nvarchar(50)  NULL
  );
END;

DECLARE @now_utc datetime2 = GETUTCDATE();
DECLARE @inst sysname = N'{{$item(0).$node["Set - Params"].json["instance_name"]}}';

INSERT INTO OpsObservability.dbo.monitoring_io_latency_history(
  ts_utc, instance_name, base_datos, archivo, lectura_ms, escritura_ms, estado
)
VALUES(
  @now_utc,
  @inst,
  N'{{$json.database}}',
  N'{{$json.file}}',
  {{$json.lectura_prom_ms || 0}},
  {{$json.escritura_prom_ms || 0}},
  N'{{$json.estado}}'
);

SELECT 1 AS ok;

