function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (ALERTA IO Latencia) ===
const P = $node["Set - Params"].json || {};
const j = $json;

const alerts = j.alerts || [];
if (!alerts.length) return [];

const tzOff = Number(P.tz_offset_hours || 0);
const toLocal = iso => {
  if (!iso) return "N/D";
  const d = new Date(iso);
  const offMs = tzOff * 3600 * 1000;
  return new Date(d.getTime() + offMs)
    .toISOString().replace("T"," ").substring(0,19);
};

const fmt = v => (v == null || v === '' || Number.isNaN(Number(v))) ? 'N/D' : String(Number(v).toFixed(2));

const inst = j.instance_name || "N/D";

const lines = alerts.map(r => {
  const db  = r.database || '-';
  const file = r.file || '-';
  const lr = fmt(r.lectura_prom_ms);
  const ew = fmt(r.escritura_prom_ms);
  const est = r.estado || '-';
  return `- **BD:** ${db}  •  **Archivo:** ${file}  •  **Lectura:** ${lr} ms  •  **Escritura:** ${ew} ms  •  **Estado:** ${est}`;
});

const diag = (P.causes_io || [
  'Picos de I/O o saturación de disco.',
  'Autogrowth o tareas pesadas en horario pico.',
  'Storage subdimensionado o colas largas.'
]).map(x => `- ${x}`).join('\n');

const sugg = (P.reco_io || [
  'Revisar latencia/colas del storage (SAN/VM/Disco).',
  'Ajustar AutoGrowth a incrementos fijos y razonables.',
  'Mover backups/jobs pesados fuera de horas pico.'
]).map(x => `- ${x}`).join('\n');

const title = `${P.title_prefix || 'ALERTA – IO Latencia'} • ${inst}`;

return {
  json: {
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: "C0392B",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text: `🔴 **ALERTA – IO Latencia**

Instancia: **${inst}**
Archivos en alerta en esta ejecución: **${alerts.length}**
Hora local: ${toLocal(j.now_utc)}`
      },
      {
        markdown: true,
        text: `📄 **Detalle**

${lines.join('\n')}`
      },
      {
        markdown: true,
        text: `📌 **Diagnóstico posible**
${diag}`
      },
      {
        markdown: true,
        text: `✅ **Sugerencias**
${sugg}`
      }
    ]
  }
};

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (RECOVERY) — IO Latencia ===
const j = $json;

const recovered   = j.recovered_items || [];
const stillAlerts = j.alerts || [];

let title = '';
const lines = [];

if (j.send_recovery_global) {
  title = 'RECOVERY – IO Latencia (todos OK)';
  lines.push('Todos los archivos monitoreados por el SP `usp_MonitoreoIOLatencia` están ahora en estado **OK** (sin alertas de latencia).');
} else {
  title = 'RECOVERY parcial – IO Latencia';
  lines.push('Algunos archivos se han recuperado, pero aún quedan archivos en **ALERTA** por latencia de I/O.');
}

if (recovered.length) {
  lines.push('');
  lines.push(`**Registros recuperados (${recovered.length}):**`);
  lines.push('');
  recovered.forEach(r => {
    const db   = r.database || r.BaseDeDatos || 'N/D';
    const file = r.file || r.Archivo || 'N/D';
    lines.push(`- **BD:** ${db}  •  **Archivo:** ${file}`);
  });
}

if (stillAlerts.length) {
  lines.push('');
  lines.push(`**Registros que siguen en alerta (${stillAlerts.length}):**`);
  lines.push('');
  stillAlerts.forEach(r => {
    const db   = r.database || r.BaseDeDatos || 'N/D';
    const file = r.file || r.Archivo || 'N/D';
    const lr = r.lectura_prom_ms != null ? Number(r.lectura_prom_ms).toFixed(2) : 'N/D';
    const ew = r.escritura_prom_ms != null ? Number(r.escritura_prom_ms).toFixed(2) : 'N/D';
    const est = r.estado || 'Alerta';
    lines.push(`- **BD:** ${db}  •  **Archivo:** ${file}  •  Lectura: ${lr} ms  •  Escritura: ${ew} ms  •  Estado: ${est}`);
  });
}

const text = `### ${title}

` + lines.join('\n');

return [{ json: { body: toAdaptiveCardBody(text) } }];

// === Function – Decidir estado (IO Latencia) con recovery por registro ===

const P = $node["Set - Params"].json || {};

// 1) Filas actuales: tomamos las que ya procesaste en "Function – Expand filas"
const rows = $items("Function – Expand filas").map(i => i.json);

// Helper: ¿esta fila está en ALERTA?
const isAlert = (r) => {
  const e = String(r.estado || r.Estado || "").toUpperCase();
  return e.startsWith("ALERTA");
};

const alerts = rows.filter(isAlert);
const oks    = rows.filter(r => !isAlert(r));

// 2) Estado global en memoria (staticData)
const staticData = $getWorkflowStaticData('global');

const last_state = staticData.last_state || "INIT"; // ALERT / OK / INIT
const state      = alerts.length > 0 ? "ALERT" : "OK";

staticData.last_state = state;

// Flags globales
const send_alert           = alerts.length > 0;
const send_recovery_global = (last_state === "ALERT" && state === "OK");

// 3) Recovery por registro (BaseDeDatos + Archivo)
staticData.items     = staticData.items || {};     // registros en alerta última vez
staticData.recovered = staticData.recovered || {}; // registros ya notificados como recovery

const prevItems    = staticData.items;
const recoveredMap = staticData.recovered;

const getKey = (r) => {
  const db   = r.database || r.BaseDeDatos || "";
  const file = r.file     || r.Archivo     || "";
  return `${db}|${file}`;
};

const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;
  currentAlertSet[k] = true;
  prevItems[k] = r;
  if (recoveredMap[k]) delete recoveredMap[k];
}

const recovered_items = [];

for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    if (!recoveredMap[k]) {
      recovered_items.push({ ...lastRow, _recovery: true });
      recoveredMap[k] = 1;
    }
    delete prevItems[k];
  }
}

const send_recovery_partial = recovered_items.length > 0;
const transition = `${last_state}->${state}`;

const now_utc = new Date().toISOString();

return [
  {
    json: {
      instance_name: P.instance_name || "N/D",
      now_utc,
      state,
      last_state,
      transition,
      total: rows.length,
      alert_count: alerts.length,
      total_ok: oks.length,
      alerts,
      oks,
      recovered_items,
      send_alert,
      send_recovery_global,
      send_recovery_partial
    }
  }
];

